// План specs/admin-plans.md, 1.10 (кейс AP-08). Только чтение: диалог закрывается «Cancel», Save НЕ нажимается. @prod-safe
import { test, expect } from '@playwright/test';
import { setLanguage, openPlansTab, targetRow, dialogFields, isoDate } from './plans-helpers';

test.use({ storageState: '../auth/admin.json' });

test.describe('Admin Panel — Plans', () => {
  test('Assign dialog rejects a past date with a message and disabled Save, then Cancel #6eed7c73 #2b3784 #b42657 #ca557707 @desktop @prod-safe', async ({ page }) => {
    await setLanguage(page, 'en');
    await openPlansTab(page);

    // Ровно одна строка «בדיקה» (targetRow падает иначе)
    const row = await targetRow(page);
    const before = (await row.innerText()).trim();

    const action = row.getByRole('button', { name: 'Assign plan', exact: true })
      .or(row.getByRole('button', { name: 'Change / extend', exact: true })).first();
    await action.click();

    const f = dialogFields(page);
    await expect(f.dialog).toBeVisible();
    await f.reason.fill('QA-AUTO past-date check');

    // У поля даты min = сегодня
    await expect(f.until).toHaveAttribute('min', isoDate(0));

    // Вчера — сообщение и Save неактивна
    await f.until.fill(isoDate(-1));
    await expect(f.dialog.getByText('Pick today or a later date.', { exact: true })).toBeVisible();
    await expect(f.save).toBeDisabled();

    // Сегодня — сообщения нет, Save активна (НЕ нажимаем)
    await f.until.fill(isoDate(0));
    await expect(f.dialog.getByText('Pick today or a later date.', { exact: true })).toHaveCount(0);
    await expect(f.save).toBeEnabled();

    // Cancel — диалог закрыт, строка не изменилась
    await f.dialog.getByRole('button', { name: 'Cancel', exact: true }).click();
    await expect(f.dialog).toBeHidden();
    await expect(row).toHaveText(before);
  });
});
